// A minimal hook dispatcher (as tests/btw-pane-render.test.mjs): renders the memo's inner component, runs effects in order.
function fixture(component, props) {
  const cells = [], effects = [];
  let cursor = 0, tree;
  const same = (a, b) => a && b && a.length === b.length && a.every((v, i) => Object.is(v, b[i]));
  const dispatcher = {
    useState(initial) { const i = cursor++; cells[i] ??= { value: typeof initial === 'function' ? initial() : initial }; return [cells[i].value, (next) => { cells[i].value = typeof next === 'function' ? next(cells[i].value) : next; }]; },
    useRef(initial) { return dispatcher.useState(() => ({ current: initial }))[0]; },
    useMemo(fn, deps) { const i = cursor++; if (!cells[i] || !same(cells[i].deps, deps)) cells[i] = { value: fn(), deps }; return cells[i].value; },
    useCallback(fn, deps) { return dispatcher.useMemo(() => fn, deps); },
    useEffect(fn, deps) { const i = cursor++; if (!cells[i] || !same(cells[i].deps, deps)) { const old = cells[i]; cells[i] = { deps }; effects.push(() => { old?.cleanup?.(); cells[i].cleanup = fn(); }); } },
    useLayoutEffect(fn, deps) { return dispatcher.useEffect(fn, deps); },
  };
  const render = (next = props) => {
    cursor = 0; props = next;
    const internals = React.__CLIENT_INTERNALS_DO_NOT_USE_OR_WARN_USERS_THEY_CANNOT_UPGRADE, old = internals.H;
    internals.H = dispatcher;
    try { tree = component(props); } finally { internals.H = old; }
    while (effects.length) effects.shift()();
    return tree;
  };
  render();
  return { get tree() { return tree; }, render };
}
const fakeWindow = () => { const listeners = []; return { listeners, addEventListener: (type, fn, capture) => listeners.push([type, capture]), removeEventListener: (type) => listeners.splice(listeners.findIndex(([t]) => t === type), 1) }; };
const node = (win) => ({ nodeType: 1, ownerDocument: { defaultView: win }, contains: () => true });
const item = (file, isDirectory = false) => ({ kind: 'file', getAsFile: () => file, webkitGetAsEntry: () => ({ isDirectory }) });
function dragEvent(win, { types = ['Files'], items = [], files = [], prevented = false } = {}) {
  const event = { dataTransfer: { types, items, files, dropEffect: 'unset' }, target: node(win), currentTarget: node(win), defaultPrevented: prevented, stopped: false,
    preventDefault() { this.defaultPrevented = true; }, stopPropagation() { this.stopped = true; }, isDefaultPrevented() { return this.defaultPrevented; } };
  return event;
}
const haloOf = (tree) => [tree.props.children].flat(2).find((child) => child && child.type === Target.DropHalo) ?? null;

test('YI: a Finder drag shows the halo, sets the copy effect, and a drop hands the mb split to onDropped (once)', () => {
  const dropped = [], win = fakeWindow();
  const zone = fixture(Zone.ComposerPaneDropZone.type, { onDropped: (split) => dropped.push(split), className: 'h-full min-w-0 flex flex-col', children: 'pane' });
  assert.equal(zone.tree.type, 'div');
  assert.equal(zone.tree.props.className, 'relative h-full min-w-0 flex flex-col');
  assert.equal(haloOf(zone.tree), null);
  const enter = dragEvent(win);
  zone.tree.props.onDragEnter(enter);
  assert.ok(enter.defaultPrevented && enter.stopped, 'claim: the zone takes the drag');
  zone.render();
  assert.ok(haloOf(zone.tree), 'the halo while a drag is over the pane');
  assert.deepEqual(win.listeners, [['dragend', true], ['drop', true]], 'the owner window clears the state on a drag that ends elsewhere');
  const over = dragEvent(win);
  zone.tree.props.onDragOver(over);
  assert.equal(over.dataTransfer.dropEffect, 'copy');
  const png = { name: 'a.png', type: 'image/png' }, txt = { name: 'b.txt', type: 'text/plain' }, dir = { name: 'src', type: '' };
  const drop = dragEvent(win, { items: [item(png), item(txt), item(dir, true)] });
  zone.tree.props.onDrop(drop);
  assert.deepEqual(dropped, [{ folders: [dir], files: [png, txt] }]);
  zone.render();
  assert.equal(haloOf(zone.tree), null, 'the halo is gone after the drop');
  assert.deepEqual(win.listeners, []);
});

test('YI: disabled refuses the drop (dropEffect none, nothing delivered, no halo); filesElsewhere without appDrag is inert', () => {
  const dropped = [], win = fakeWindow();
  const off = fixture(Zone.ComposerPaneDropZone.type, { onDropped: (split) => dropped.push(split), disabled: true, children: 'pane' });
  off.tree.props.onDragEnter(dragEvent(win));
  off.render();
  assert.equal(haloOf(off.tree), null);
  const over = dragEvent(win);
  off.tree.props.onDragOver(over);
  assert.equal(over.dataTransfer.dropEffect, 'none');
  off.tree.props.onDrop(dragEvent(win, { items: [item({ name: 'a.png', type: 'image/png' })] }));
  assert.deepEqual(dropped, []);
  // Chat / Cowork: the host pane box keeps the zone mounted but inert, so their cards' own drop runs untouched.
  const inert = fixture(Zone.ComposerPaneDropZone.type, { onDropped: (split) => dropped.push(split), filesElsewhere: true, children: 'pane' });
  for (const name of ['onDragEnter', 'onDragOver', 'onDrop']) {
    const event = dragEvent(win, { items: [item({ name: 'a.png', type: 'image/png' })] });
    inert.tree.props[name](event);
    assert.ok(!event.defaultPrevented && !event.stopped, name);
    assert.equal(event.dataTransfer.dropEffect, 'unset', name);
  }
  inert.render();
  assert.equal(haloOf(inert.tree), null);
  assert.deepEqual(dropped, []);
});

test('YI: an in-app drag the pane owns (appDrag, cd06fb298 g) commits instead of reaching onDropped', () => {
  const dropped = [], commits = [], win = fakeWindow();
  const appDrag = { accepts: (event) => event.dataTransfer.types.includes('application/x-owned'), onDrop: () => commits.push('commit') };
  const zone = fixture(Zone.ComposerPaneDropZone.type, { onDropped: (split) => dropped.push(split), appDrag, filesElsewhere: true, children: 'pane' });
  zone.tree.props.onDragEnter(dragEvent(win, { types: ['application/x-owned'] }));
  zone.render();
  assert.ok(haloOf(zone.tree));
  zone.tree.props.onDrop(dragEvent(win, { types: ['application/x-owned'] }));
  assert.deepEqual(commits, ['commit']);
  assert.deepEqual(dropped, []);
  // The host's appDrag is the file-context drag wrapper for the pane's owner; none without an owner or a live drag.
  assert.equal(PaneDrop.paneAppDrag(null), undefined);
  const host = PaneDrop.paneAppDrag({});
  assert.equal(host.accepts(dragEvent(win, { types: ['Files'] })), false, 'no file-context drag in flight');
  assert.equal(typeof host.onDrop, 'function');
});

test('SSR: the host zone is YI around the pane box, the halo is the official ring, and every class is in the loaded sheet', () => {
  const html = renderToStaticMarkup(h(PaneDrop.SourcePaneDropZone, { dropRef: { current: null }, owner: {} }, h('div', { className: 'source-chat-tile-content' })));
  assert.equal(html, '<div class="relative h-full min-w-0 flex flex-col"><div class="source-chat-tile-content"></div></div>');
  const halo = renderToStaticMarkup(h(Target.DropHalo));
  assert.match(halo, /^<div class="pointer-events-none absolute inset-0 rounded shadow-\[inset_0_0_0_2px_var\(--cds-fill-accent\)\] motion-safe:animate-\[cds-drop-ring-in_0\.15s_cubic-bezier\(0\.215,0\.61,0\.355,1\)\]" style="z-index:40"><div class="absolute inset-0 rounded-\[inherit\]/);
  const sheets = ['shared-frame-CegduNQ2.css', 'shared-styles-Bl9zqrv-.css', 'c6a992d55-sXiDGMFQ.css', 'ce598b86c-CctVJsaN.css', 'c3fde7009-BH42YUtA.css']
    .map((f) => fs.readFileSync(path.join(app, 'public/assets/v1', f), 'utf8')).join('\n');
  const escape = (token) => '.' + token.replace(/[^a-zA-Z0-9_-]/g, (c) => '\\' + c);
  const tokens = [...new Set([...`${html}${halo}`.matchAll(/class="([^"]*)"/g)].flatMap((m) => m[1].split(/\s+/)).filter((t) => t && t !== 'source-chat-tile-content'))];
  assert.deepEqual(tokens.filter((t) => !['{', ':', ',', '[', ' ', '>', ')', '.'].some((next) => sheets.includes(escape(t) + next))), []);
  assert.ok(sheets.includes('@keyframes cds-drop-ring-in'));
});

test('wiring: main.jsx wraps the session pane box in the zone, the Code composer publishes its drop and its card takes none', () => {
  const main = fs.readFileSync(path.join(app, 'src/main.jsx'), 'utf8');
  assert.equal(count(main, 'import { SourcePaneDropZone } from "./source-composer-pane-drop.jsx";'), 1);
  assert.equal(count(main, '<SourcePaneDropZone dropRef={paneDropRef} owner={fileContextOwner} filesElsewhere={mode !== "code"} disabled={!composerAttachable}>\n          <div className="source-chat-tile-content"'), 1);
  assert.equal(count(main, '          </div>\n          </SourcePaneDropZone>\n          )} />'), 1);
  assert.equal(count(main, 'dropRef={mode === "code" ? paneDropRef : undefined}'), 1);
  const composer = fs.readFileSync(path.join(app, 'src/source-composer.jsx'), 'utf8');
  assert.equal(count(composer, 'const paneDrop = mode === "code" && !!dropRef;'), 1);
  assert.equal(count(composer, 'dropRef.current = acceptsFiles ? (split) => { intake(split, "drop"); editor.current?.focus?.(); } : null;'), 1);
  assert.equal(count(composer, '{...(paneDrop ? {} : {'), 1, 'the card drop handlers only without the pane zone');
});

test('/btw: the side-session composer sits in CdsRoot (density, platform desktop, the Code pane experimental, contents)', () => {
  const s = { threads: {}, active: {}, items: { child: [] }, approvals: [], approvalConnectionId: 'connection', approvalConnectionEpoch: 1 };
  const html = renderToStaticMarkup(h(Btw.SourceBtwPane, { sessionId: 'child', density: 'compact', meta: { btw: { permission: 'ask' } }, thread: { id: 'child', cwd: '/repo' },
    tabs: [{ id: 'child', name: 'btw: Question' }], state: s, connected: true, onLoad: noop, onSend: noop, onStop: noop, onSelect: noop, onCloseTab: noop, onError: noop }));
  const root = /<div class="cds-root text-primary contents"([^>]*)>/.exec(html);
  assert.ok(root, 'a CdsRoot box');
  assert.match(root[1], /data-density="compact"/);
  assert.match(root[1], /data-platform="desktop"/);
  // No font prop: CdsRoot reads html[data-font] (nr); without a document it falls back to "anthropic" in SSR.
  assert.match(root[1], /data-font="/);
  assert.ok(html.indexOf(root[0]) < html.indexOf('data-embedded="true"'), 'the composer zone is inside it');
  const source = fs.readFileSync(path.join(app, 'src/source-btw-pane.jsx'), 'utf8');
  assert.equal(count(source, '<CdsRoot density={density} platform="desktop" experimental={codePaneExperimental} className="contents">'), 1);
  assert.equal(count(source, '</CdsRoot>'), 1);
});

test('Video tile: shared-2 Ap through c0fbbe82d gr renders the original MessageAttachmentsVideo; Vi picks it only for a File-backed video', () => {
  assert.equal(count(official('c0fbbe82d-BOWKSems.js'), 'e.file!==void 0&&Ze.test(e.fileName)&&Si.test(e.file.type)?f(gr,{file:e.file,'), 1);
  assert.equal(count(official('shared-2-Cb74JByF.js'), '"data-cds":"MessageAttachmentsVideo"'), 1);
  const tile = renderToStaticMarkup(h(Wrappers.ComposerVideoTile, { file: { type: 'video/mp4' }, name: 'clip.mp4', onRemove: noop }));
  assert.match(tile, /data-cds="MessageAttachmentsVideo"/);
  assert.match(tile, /data-cds-attachment=""/);
  const direct = renderToStaticMarkup(h(Attachments.AttachmentVideo, { name: 'clip.mp4' }));
  assert.match(direct, /data-cds="MessageAttachmentsVideo"/);
  // A host entry keeps no File: the strip still draws a File tile for a video by path.
  const strip = renderToStaticMarkup(h(Tiles.ComposerAttachmentTiles, { entries: [{ id: 'v', kind: 'file', name: 'clip.mp4', path: '/repo/clip.mp4', status: 'ready' }] }));
  assert.match(strip, /data-cds="MessageAttachmentsFile"/);
  assert.doesNotMatch(strip, /MessageAttachmentsVideo/);
});
